import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"10、【履】 兌下乾上","description":"周易口訣義 - 10、【履】 兌下乾上","frontmatter":{"title":"10、【履】 兌下乾上","description":"周易口訣義 - 10、【履】 兌下乾上"},"headers":[],"relativePath":"classics/koujueyi/012.md","filePath":"classics/koujueyi/012.md"}'),r={name:"classics/koujueyi/012.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_10、【履】-兌下乾上" tabindex="-1">10、【履】 兌下乾上 <a class="header-anchor" href="#_10、【履】-兌下乾上" aria-label="Permalink to “10、【履】 兌下乾上”">​</a></h1><p>彖曰：履，柔履剛也。說而應乎乾，是以「履虎尾，不咥人，亨」。剛中正，履帝位而不疚，光明也。</p><p>象曰：上天下澤，履。君子以辨上下，定民志。</p><p>初九：素履往，無咎。</p><p>象曰：素履之往，獨行願也。</p><p>九二：履道坦坦，幽人貞吉。</p><p>象曰：「幽人貞吉」，中不自亂也。</p><p>六三：眇能視，跛能履，履虎尾，咥人，兇。武人為於大君。</p><p>象曰：「眇能視」，不足以有明也。「跛能履」，不足以與行也。咥人之兇，位不當也。「武人為於大君」，志剛也。</p><p>九四：履虎尾，訴訴，終吉。象曰：「訴訴終吉」，志行也。</p><p>九五：夬履，貞厲。</p><p>象曰：「夬履貞厲」，位正當也。</p><p>上九：視履考祥，其旋元吉。</p><p>象曰：元吉在上，大有慶也。</p><p>解讀</p><p>「履虎尾，不咥人，亨」者，履，禮也，踐也。故先儒雲：「統之於心曰體，踐而行之曰履。」夫禮尚卑謙，今六三以柔乘剛，違謙越禮，如履踐虎尾，言其危懼之甚也。「不咥人亨」者，咥，齧也；雖復履踐虎尾，以其悅奉於剛正之德，所以不被咥齧而得亨通也。</p><p>象曰：「上天下澤，履，君子以辨上下，定民志」者，天尊澤卑，各得其序，故曰「履，禮之象也」。君子以分辨上下，君臣有禮，正定人民志意，使尊卑有別也。</p><p>「初九，素履，往無咎」者，禮貴儉約，今初九處履之初，不尚華飾，以質素為用，既行其禮以素，可以往而「無咎」矣。</p><p>「九二，履道坦坦，幽人貞吉」者，坦坦，平易之貌。九二陽居陰而用卑巽，往之於應，途路平坦，無所險厄，故曰「履道坦坦」也。在內履中，謙巽以行，不以處內為屈，居外為榮，是幽隱之人，而不失貞正之道，故曰「幽人貞吉」也。</p><p>「六三，眇能視，跛能履，履虎尾，咥人兇，武人為於大君」者，以陰居陽，不行謙巽之道，猶如眇目之人，所視不明也，跛足之人，所行不能遠也。既無謙巽之行，則為物害，猶如履踐虎尾，必見咥齧，所以「兇」也。以微劣之軀，而欲行其剛武，為於大君，是兇頑之甚，故曰「武人為於大君」也。</p><p>「九四：履虎尾，訴訴，終吉」者，子夏傳：「訴訴，恐懼之貌也」。九四逼近至尊，心之憂懼，若蹈虎尾而訴訴恐懼，故書雲「若蹈虎尾，涉於春冰」是也。以陽居陰，用之謙巽，上奉於君，故「終吉」也。</p><p>「九五：夬履，貞厲」者，夬，決也；為履之主，裁之以義，正之以禮，故以剛決貞，故曰「夬履，貞厲」也。然以陽居尊，滿之道矣。禮尚謙虛，而以盈滿為用，是危厲者也。</p><p>上九：視履考祥，其旋元吉者，考，是察也；祥，謂禎祥也；旋，反也。上九處履之極，能察禍福禎祥也。又能視其所履踐之德行，不為驕怠，而能旋反行禮，以應尊卑，施惠向下，故獲「大吉」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
